WITH page_sales AS ( SELECT cp.cp_catalog_page_sk, cp.cp_catalog_page_id, cp.cp_department, cp.cp_catalog_number, SUM(cs.cs_net_profit) AS total_net_profit, SUM(cs.cs_quantity) AS total_quantity FROM catalog_sales cs INNER JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk INNER JOIN date_dim d ON cs.cs_sold_date_sk = d.d_date_sk WHERE d.d_year = 2022 GROUP BY cp.cp_catalog_page_sk, cp.cp_catalog_page_id, cp.cp_department, cp.cp_catalog_number ), ranked_pages AS ( SELECT cp_catalog_page_id, cp_department, cp_catalog_number, total_net_profit, total_quantity, CASE WHEN total_net_profit > 100000 THEN 'High' WHEN total_net_profit > 50000 THEN 'Medium' ELSE 'Low' END AS profit_category, RANK() OVER (ORDER BY total_net_profit DESC) AS profit_rank FROM page_sales ) SELECT cp_catalog_page_id, cp_department, cp_catalog_number, total_net_profit, total_quantity, profit_category, profit_rank FROM ranked_pages WHERE profit_rank <= 10 ORDER BY profit_rank
